import {createGame,stepDemo,PRODUCTS,PERSONALITIES,money} from './engine.js';
let state=createGame(),selected='atlas',running=false,busy=false,timer=null,speed=1000,filter='all',notice='',setup=false,local=false,mode='demo';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const total=k=>state.agents.reduce((n,a)=>n+a[k],0);
const sum=o=>Object.values(o).reduce((n,x)=>n+x,0);
function chart(){
  if(state.history.length<2)return '<div class="chart-empty">Every business starts at $500.<p>Run the simulation to see strategies diverge.</p></div>';
  const values=state.history.flatMap(h=>h.cash),lo=Math.min(0,...values),hi=Math.max(60000,...values)*1.08;
  const y=v=>180-(v-lo)/(hi-lo)*165,x=d=>45+d/Math.max(1,state.day)*665;
  return `<svg class="chart" viewBox="0 0 720 195" role="img" aria-label="Bank balance over the season for each agent">${[0,.5,1].map(f=>{const v=lo+f*(hi-lo);return `<line x1="45" x2="710" y1="${y(v)}" y2="${y(v)}" stroke="#30392e" stroke-dasharray="3 5"/><text x="0" y="${y(v)+3}" fill="#8e9d8c" font-size="9">$${Math.round(v/100)}</text>`;}).join('')}${state.agents.map((a,i)=>`<polyline points="${state.history.map(h=>`${x(h.day)},${y(h.cash[i])}`).join(' ')}" fill="none" stroke="${a.color}" stroke-width="2" stroke-linejoin="round"/>`).join('')}</svg><div class="chart-labels"><span>DAY 0</span><span>DAY ${state.day}</span></div>`;
}
function render(){
  const a=state.agents.find(x=>x.id===selected),ranking=[...state.agents].sort((a,b)=>b.cash-a.cash),logs=state.log.filter(e=>filter==='all'||e.agent===filter).slice(-80).reverse();
  $('#app').innerHTML=`<header><div class="brand"><span class="brand-mark">va.</span> vending arena</div><div class="header-right"><span><i class="live-dot"></i>AN AUTONOMOUS ECONOMY</span><a href="https://andonlabs.com/evals/vending-bench-2" target="_blank" rel="noreferrer">The inspiration ↗</a></div></header>
  <main><div class="intro"><div><div class="eyebrow">Four agents. One market. ${state.days} days.</div><h1>Small business.<br><em>Independent minds.</em></h1><p>Give agents a vending machine. Let their strategies do the talking.</p></div><div class="season-pill mono">SEASON 01 <span style="color:var(--muted)">/ SEED ${state.seed}</span></div></div>
  ${notice?`<div class="notice" role="alert">${esc(notice)}</div>`:''}
  ${setup?`<section class="setup"><h2>Start a new season</h2><div class="setup-fields"><label>Market seed<input id="seed" type="number" min="0" max="4294967295" value="${state.seed}"></label><label>Start date<input id="start-date" type="date" value="${state.startDate}"></label><label>Season length<select id="days"><option value="30" ${state.days===30?'selected':''}>30 days</option><option value="90" ${state.days===90?'selected':''}>90 days</option><option value="365" ${state.days===365?'selected':''}>365 days</option></select></label><button class="button primary" id="create">Start fresh</button><button class="button" id="cancel">Cancel</button></div><p class="help">Replaces the current season. Export it first if you want to keep it.</p></section>`:''}
  <div class="controls"><button class="button primary" id="play" ${(busy&&!running)||state.phase==='finished'?'disabled':''}>${running?'Ⅱ Pause season':'▶ Run season'}</button><button class="button" id="step" ${busy||running||state.phase==='finished'?'disabled':''}>Next day →</button><label>Speed<select id="speed"><option value="1000" ${speed===1000?'selected':''}>1×</option><option value="350" ${speed===350?'selected':''}>3×</option><option value="80" ${speed===80?'selected':''}>10×</option></select></label><span class="spacer"></span><span class="status" role="status">${busy?'Agents are deciding…':state.phase==='finished'?'Season complete':running?'Market is running':'Market is paused'}</span><button class="button" id="new" ${busy?'disabled':''}>New season</button></div>
  <div class="progress" aria-label="Season progress"><span style="width:${state.day/state.days*100}%"></span></div>
  <section class="arena"><div class="arena-top"><div class="place">◉ Mission Bay Plaza <span>San Francisco · Shared customer market</span></div><div class="market"><span>${state.weather==='Hot'?'☀':state.weather==='Rainy'?'☂':'◌'} ${state.weather}</span><span>${state.unitsSoldToday} units sold today</span><span class="mono">DAY ${String(state.day).padStart(3,'0')} / ${state.days}</span></div></div>
  <div class="agents">${state.agents.map((a,i)=>`<button class="agent ${selected===a.id?'selected':''}" data-agent="${a.id}" style="--accent:${a.color}" aria-pressed="${selected===a.id}" aria-label="Inspect ${a.name}"><div class="agent-title"><span class="agent-name">${a.name}</span><span class="agent-index">0${i+1} ↗</span></div><span class="tag">${mode==='codex'?'CODEX AGENT':a.strategy.toUpperCase()+' POLICY'}${!a.active?' · CLOSED':''}</span><div class="stock-preview">${PRODUCTS.map(p=>`<div class="stock-cell"><span class="icon" aria-hidden="true">${p.icon}</span><small>${a.inventory[p.id]} / 30</small></div>`).join('')}</div><div class="agent-bottom"><div><div class="small-label">Bank balance</div><div class="cash mono">${money(a.cash)}</div></div><div class="delta mono">${a.cash>=50000?'+':''}${((a.cash/50000-1)*100).toFixed(1)}%</div></div></button>`).join('')}</div>
  <div class="arena-footer"><span>SELECT A MACHINE TO INSPECT ITS BUSINESS</span><span>${state.calendar.date} · $2 daily rent per machine</span></div></section>
  <div class="metric-row"><div class="metric"><div class="eyebrow">Market revenue</div><strong class="mono">${money(total('revenue'))}</strong><small>Gross sales across all machines</small></div><div class="metric"><div class="eyebrow">Items sold</div><strong class="mono">${total('sold').toLocaleString()}</strong><small>Realized simulated purchases</small></div><div class="metric"><div class="eyebrow">Cash change</div><strong class="mono">${money(total('cash')-200000)}</strong><small>After stock and rent</small></div><div class="metric"><div class="eyebrow">Market leader</div><strong>${state.day===0?'Undecided':ranking[0].name}</strong><small>${state.day===0?'All agents start on equal footing':money(ranking[0].cash)+' bank balance'}</small></div></div>
  ${state.phase==='finished'?`<p class="finished">Season finished. ${ranking[0].name} leads with ${money(ranking[0].cash)} in cash. Inventory has no liquidation value.</p>`:''}
  <div class="grid"><section class="panel"><div class="panel-head"><h2>The long game</h2><div class="legend">${state.agents.map(a=>`<span><i style="background:${a.color}"></i>${a.name}</span>`).join('')}</div></div><p class="help">Bank balance · USD</p>${chart()}</section><section class="panel"><div class="panel-head"><h2>Leaderboard</h2><span class="eyebrow">By bank balance</span></div>${ranking.map((a,i)=>`<div class="rank-row"><span class="rank-number">0${i+1}</span><div class="rank-name">${a.name} <span style="color:var(--muted);font-size:10px">/ ${mode==='codex'?'Codex':a.strategy}</span><div class="rank-bar"><span style="width:${Math.max(0,a.cash/Math.max(1,ranking[0].cash)*100)}%;background:${a.color}"></span></div></div><span class="rank-cash mono">${money(a.cash)}</span></div>`).join('')}</section></div>
  <section class="panel detail"><div class="panel-head"><h2><span style="color:${a.color}">◉</span> Inside ${a.name}’s business</h2><span class="tag" style="--accent:${a.color}">${a.active?'OPERATING':'CLOSED'}</span></div><div class="detail-grid"><div><div class="eyebrow">Latest decision</div><div class="quote">“${esc(a.rationale)}”</div><div class="eyebrow" style="margin-bottom:10px">Agent notebook</div><div class="note">${esc(a.memory||'No decisions yet. Run the first day to open the business.')}</div><p class="help">${a.orders.length} deliveries pending · ${money(a.spending)} stock purchased · ${money(a.fees)} rent paid · ${money(a.arrears)} rent owed</p></div><div><table><thead><tr><th>Product</th><th>Price</th><th>Machine</th><th>Storage</th><th>Sold today</th></tr></thead><tbody>${PRODUCTS.map(p=>`<tr><td>${p.icon} ${p.name}</td><td class="mono">${money(a.prices[p.id])}</td><td>${a.inventory[p.id]}/30</td><td>${a.storage[p.id]}</td><td>${a.lastSales[p.id]}</td></tr>`).join('')}</tbody></table></div></div></section>
  <section class="panel" style="margin-top:22px"><div class="panel-head"><h2>How sales are calculated</h2><span class="eyebrow">Paper-based · local calibration</span></div><p>Daily product demand follows the stages in <a href="https://arxiv.org/html/2502.15840v1#S2.SS2.SSS2" target="_blank" rel="noreferrer">Vending-Bench §2.2.2</a>: price elasticity, baseline demand, calendar and weather effects, assortment variety, noise, rounding and stock limits.</p><p class="help">The paper does not publish exact coefficients or its cached product values. This game uses labeled local estimates and a local rule to share demand across machines. Sales below are product demand, not a count of individual visitors. Export includes the full calibration and today’s calculation breakdown.</p>${state.salesReport.length?`<table><thead><tr><th>Product</th><th>Expected market units</th><th>After noise</th><th>Units sold</th></tr></thead><tbody>${state.salesReport.map(r=>`<tr><td>${PRODUCTS.find(p=>p.id===r.product).name}</td><td>${r.expected.toFixed(1)}</td><td>${r.demand}</td><td>${r.sold}</td></tr>`).join('')}</tbody></table>`:''}</section>
  <section class="panel feed"><div class="panel-head"><h2>Life in the market</h2><label><span class="sr-only">Filter activity by agent</span><select id="filter"><option value="all">All activity</option>${PERSONALITIES.map(a=>`<option value="${a.id}" ${filter===a.id?'selected':''}>${a.name}</option>`).join('')}</select></label></div><div class="feed-list">${logs.length?logs.map(e=>`<div class="feed-item"><span class="feed-day">D${String(e.day).padStart(3,'0')}</span><span style="color:${PERSONALITIES.find(a=>a.id===e.agent)?.color||'#8e9d8c'}">${PERSONALITIES.find(a=>a.id===e.agent)?.name||'Market'}</span><span class="feed-text">${esc(e.text)}</span></div>`).join(''):'<div class="feed-empty">The plaza is quiet. Start the season to see orders, deliveries, decisions and sales.</div>'}</div></section>
  <section class="panel" style="margin-top:22px"><div class="panel-head"><h2>Who’s making the decisions?</h2><label><span class="sr-only">Agent engine</span><select id="mode" ${busy||running?'disabled':''}><option value="demo" ${mode==='demo'?'selected':''}>Built-in strategies</option><option value="codex" ${mode==='codex'?'selected':''} ${local?'':'disabled'}>Codex agents${local?'':' · local runner required'}</option></select></label></div><p>${mode==='demo'?'You’re watching four transparent, rule-based strategies. They react to the same simulated market. No language model is running in this mode.':'Each agent uses the local Codex harness to choose prices, load stock and place orders. Agents retain a private notebook between daily decisions. Calls use your configured Codex account.'}</p><p class="help">${local?'Codex mode: one model call per active agent per day. Speed controls the pause between decision rounds; model calls take additional time. Switching modes starts a new season.':'For autonomous language-model agents, run this project locally with npm start and select Codex agents. This preview runs the complete market simulation in your browser.'} Experiments are inspired by Vending-Bench; this is an independent game, not the official benchmark. Progress lasts for this tab session. Export a season to keep its complete event log.</p><button class="button" id="export">↓ Export season JSON</button></section>
  <footer><span>VENDING ARENA · A SMALL EXPERIMENT IN AUTONOMY</span><span>Same market. Different decisions. Simulated money.</span></footer></main>`;
  $('#play').onclick=()=>{running=!running;render();schedule();};$('#step').onclick=advance;
  $('#speed').onchange=e=>{speed=Number(e.target.value);schedule();};
  $('#new').onclick=()=>{running=false;clearTimeout(timer);setup=!setup;render();};
  if($('#cancel'))$('#cancel').onclick=()=>{setup=false;render();};
  if($('#create'))$('#create').onclick=async()=>{const seed=Number($('#seed').value),days=Number($('#days').value),startDate=$('#start-date').value;try{await reset({seed,days,startDate});setup=false;render();}catch(e){notice=e.message;render();}};
  document.querySelectorAll('[data-agent]').forEach(b=>b.onclick=()=>{selected=b.dataset.agent;render();});
  $('#filter').onchange=e=>{filter=e.target.value;render();};
  $('#mode').onchange=async e=>{const requested=e.target.value;try{await reset({seed:state.seed,days:state.days,startDate:state.startDate},requested);}catch(e){notice=e.message;}render();};
  $('#export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`vending-arena-${state.seed}-day-${state.day}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
}
function schedule(){clearTimeout(timer);if(running&&!busy&&state.phase!=='finished')timer=setTimeout(advance,speed);}
async function request(path,body){const r=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const data=await r.json();if(!r.ok)throw new Error(data.error||'The local runner could not complete the request.');if(data.version&&data.version!==2)throw new Error('Restart the local server and start a new season to use the updated sales model.');return data;}
async function reset(options,nextMode=mode){running=false;clearTimeout(timer);const fresh=createGame({...options,mode:nextMode});if(nextMode==='codex')state=await request('/api/reset',{...options,mode:nextMode});else state=fresh;mode=nextMode;notice='';}
async function advance(){if(busy||state.phase==='finished')return;busy=true;render();try{state=mode==='codex'?await request('/api/step',{}):stepDemo(state);notice='';}catch(e){notice=e.message;running=false;}finally{busy=false;if(state.phase==='finished')running=false;render();schedule();}}
render();
if(['localhost','127.0.0.1','[::1]'].includes(location.hostname))fetch('/api/status').then(r=>r.ok?r.json():null).then(d=>{local=d?.local===true;render();}).catch(()=>{});
// Optional browser agent interface. The visible controls use these same actions.
if(document.modelContext?.registerTool){
  const lifecycle=new AbortController();
  const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
  register({name:'read_vending_arena',description:'Read the current season, agent balances, stocks and public decision log.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>structuredClone(state)});
  register({name:'advance_vending_demo',description:'Advance the built-in-strategy simulation by 1 to 30 days while paused. Does not run paid Codex calls.',inputSchema:{type:'object',properties:{days:{type:'integer',minimum:1,maximum:30}},required:['days'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!Number.isInteger(input?.days)||input.days<1||input.days>30)throw new Error('Days must be an integer between 1 and 30.');if(mode!=='demo'||busy||running)throw new Error('Pause a built-in-strategy season first.');for(let i=0;i<input.days&&state.phase!=='finished';i++)state=stepDemo(state);render();return {day:state.day,phase:state.phase,balances:state.agents.map(a=>({name:a.name,cash:a.cash}))};}});
  addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
